 "content": "from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == 0 or color == 2 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objects.append({'color': color, 'cells': cells})
    # Move all colored objects stepwise toward the row of color 2.
    # The boundary direction is determined by where that solid line lies.
    marker_rows = [r for r in range(h) if all(v == 2 for v in g[r])]
    upward = bool(marker_rows and marker_rows[0] == 0)
    dr = -1 if upward else 1
    occupied = {(r,c) for r in range(h) for c in range(w) if g[r][c] == 2}
    positions = [set(o['cells']) for o in objects]
    while True:
        moved = False
        # Sequential front-to-back updates let trailing objects follow as gaps open.
        order = sorted(range(len(objects)), key=lambda i: (min(r for r,c in positions[i]) * dr))
        for i in order:
            pos = positions[i]
            targets = {(r+dr,c) for r,c in pos}
            other = occupied.copy()
            for j,p in enumerate(positions):
                if j != i: other.update(p)
            if all(0 <= r < h and (r,c) not in other for r,c in targets):
                positions[i] = targets
                moved = True
        if not moved:
            break
    out = [[0]*w for _ in range(h)]
    for r,c in occupied:
        out[r][c] = 2
    for obj,pos in zip(objects,positions):
        for r,c in pos:
            out[r][c] = obj['color']
    return out
